// Merge the two Pipeworx calls into the tape schema.
// The MCP response is SSE-framed: the payload sits on a 'data: ' line, and the tool's own
// text block may itself be a JSON string containing JSON — decode twice.
const CAT = new Set(['acquisition','merger','earnings','guidance','fda','trial','offering','halt','downgrade','guidance-cut','spin','dividend','other']);

function docsOf(node) {
  const raw = node?.json?.raw ?? node?.json?.data ?? node?.json;
  let text = typeof raw === 'string' ? raw : JSON.stringify(raw ?? {});
  const out = [];
  for (const m of text.matchAll(/data: (.+)/g)) {
    let b = m[1];
    for (let i = 0; i < 3; i++) { try { b = JSON.parse(b); } catch { break; } }
    if (b && typeof b === 'object') {
      const inner = b.result?.content?.[0]?.text ?? b.content?.[0]?.text;
      if (typeof inner === 'string') { try { out.push(JSON.parse(inner)); } catch {} }
      else if (inner && typeof inner === 'object') out.push(inner);
    }
  }
  return out;
}

const trending = {}, movers = {};
for (const item of $input.all()) {
  for (const d of docsOf(item)) {
    if (Array.isArray(d.symbols)) {
      for (const s of d.symbols) {
        const t = s.trends || {};
        trending[(s.symbol || '').toUpperCase()] = {
          name: s.title, why: (t.summary || '').trim() || null,
          ts: t.summary_at || null, score: s.trending_score ?? null };
      }
    }
    if (Array.isArray(d.movers)) {
      for (const m of d.movers) movers[(m.symbol || '').toUpperCase()] = m;
    }
  }
}

const now = $now.setZone('America/New_York').toFormat("yyyy-MM-dd'T'HH:mm:ssxxx");
const rows = [], seen = new Set();
for (const tk of Object.keys(movers)) {
  if (seen.has(tk)) continue; seen.add(tk);
  const m = movers[tk], t = trending[tk];
  rows.push({ ts: now, src: 'tv', ticker: tk, name: m.name || (t && t.name) || null,
    pct: m.change_pct ?? null, price: m.price ?? null, cat: 'other',
    why: (t && t.why) || null, ref: null,
    conf: (t && t.why) ? 'high' : 'low',
    trending_ts: (t && t.ts) || null, trending_score: (t && t.score) ?? null,
    volume: m.volume ?? null, exchange: m.exchange ?? null });
}
for (const tk of Object.keys(trending)) {
  if (seen.has(tk)) continue; seen.add(tk);
  const t = trending[tk];
  rows.push({ ts: now, src: 'grok', ticker: tk, name: t.name || null, pct: null, price: null,
    cat: 'other', why: t.why, ref: null, conf: t.why ? 'high' : 'low',
    trending_ts: t.ts || null, trending_score: t.score ?? null, volume: null, exchange: null });
}
return rows.map(o => ({ json: o }));
